import { slugify } from "./slug.js";

const cases = [
  ["Hello, World!", "hello-world"],
  ["  Multiple   spaces  ", "multiple-spaces"],
  ["C++ & TypeScript", "c-typescript"],
  ["Already-slug", "already-slug"],
  ["", ""],
];

for (const [input, expected] of cases) {
  let actual;
  try {
    actual = slugify(input);
  } catch (error) {
    console.error(`slugify threw for ${JSON.stringify(input)}: ${error.message}`);
    process.exit(1);
  }
  if (actual !== expected) {
    console.error(
      `slugify(${JSON.stringify(input)}) = ${JSON.stringify(actual)}, expected ${JSON.stringify(expected)}`,
    );
    process.exit(1);
  }
}

console.log("slugify ok");
